import React from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import ContextoHistorico from './components/ContextoHistorico';
import Timeline from './components/Timeline';
import Importancia from './components/Importancia';
import PropuestaInnovadora from './components/PropuestaInnovadora';
import PublicoObjetivo from './components/PublicoObjetivo';
import TripleHelice from './components/TripleHelice';
import CuadrupleHelice from './components/CuadrupleHelice';
import AporteDesarrollo from './components/AporteDesarrollo';
import Aprendizajes from './components/Aprendizajes';
import Conclusion from './components/Conclusion';
import Footer from './components/Footer';
import './styles/App.css';

const App = () => {
    return (
        <div className="App">
            <Header />
            <Hero />
            <ContextoHistorico />
            <Timeline />
            <Importancia />
            <PropuestaInnovadora />
            <PublicoObjetivo />
            <TripleHelice />
            <CuadrupleHelice />
            <AporteDesarrollo />
            <Aprendizajes />
            <Conclusion />
            <Footer />
        </div>
    );
};

export default App;
